/**
 * @fileoverview Tests for prefer-named-capture-group rule.
 * @author Pig Fang <https://github.com/g-plane>
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/prefer-named-capture-group"),
    { RuleTester } = require("../../../lib/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester({ parserOptions: { ecmaVersion: 2018 } });

ruleTester.run("prefer-named-capture-group", rule, {
    valid: [
        "/normal_regex/",
        "/(?:[0-9]{4})/",
        "/(?<year>[0-9]{4})/",
        "/\\u{1F680}/u",
        "new RegExp()",
        "new RegExp(foo)",
        "new RegExp('')",
        "new RegExp('(?<year>[0-9]{4})')",
        "RegExp()",
        "RegExp(foo)",
        "RegExp('')",
        "RegExp('(?<year>[0-9]{4})')",
        "RegExp('(')", // invalid regexp should be ignored
        "RegExp('\\\\u{1F680}', 'u')",
        "new globalThis.RegExp('([0-9]{4})')",
        {
            code: "new globalThis.RegExp('([0-9]{4})')",
            env: { es6: true }
        },
        {
            code: "new globalThis.RegExp('([0-9]{4})')",
            env: { es2017: true }
        },
        {
            code: "new globalThis.RegExp()",
            env: { es2020: true }
        },
        {
            code: "new globalThis.RegExp(foo)",
            env: { es2020: true }
        },
        {
            code: "globalThis.RegExp(foo)",
            env: { es2020: true }
        },
        {
            code: `
                var globalThis = bar;
                globalThis.RegExp(foo);
                `,
            env: { es2020: true }
        },
        {
            code: `
                function foo () {
                    var globalThis = bar;
                    new globalThis.RegExp(baz);
                }
                `,
            env: { es2020: true }
        },

        // ES2024
        "new RegExp('(?<c>[[A--B]])', 'v')",

        /*
         * This testcase checks if the rule understands the v flag correctly.
         * Without the v flag, `([\q])` is considered a valid regex and the rule reports,
         * but if the v flag is understood correctly the rule does not because of a syntax error.
         */
        String.raw`new RegExp('([\\q])', 'v')` // SyntaxError
    ],

    invalid: [
        {
            code: "/([0-9]{4})/",
            errors: [{
                messageId: "required",
                type: "Literal",
                data: { group: "([0-9]{4})" },
                line: 1,
                column: 1,
                endColumn: 13,
                suggestions: [
                    {
                        messageId: "addGroupName",
                        output: "/(?<temp1>[0-9]{4})/"
                    },
                    {
                        messageId: "addNonCapture",
                        output: "/(?:[0-9]{4})/"
                    }
                ]
            }]
        },
        {
            code: "new RegExp('([0-9]{4})')",
            errors: [{
                messageId: "required",
                type: "NewExpression",
                data: { group: "([0-9]{4})" },
                line: 1,
                column: 1,
                endColumn: 25,
                suggestions: [
                    {
                        messageId: "addGroupName",
                        output: "new RegExp('(?<temp1>[0-9]{4})')"
                    },
                    {
                        messageId: "addNonCapture",
                        output: "new RegExp('(?:[0-9]{4})')"
                    }
                ]
            }]
        },
        {
            code: "RegExp('([0-9]{4})')",
            errors: [{
                messageId: "required",
                type: "CallExpression",
                data: { group: "([0-9]{4})" },
                line: 1,
                column: 1,
                endColumn: 21,
                suggestions: [
                    {
                        messageId: "addGroupName",
                        output: "RegExp('(?<temp1>[0-9]{4})')"
                    },
                    {
                        messageId: "addNonCapture",
                        output: "RegExp('(?:[0-9]{4})')"
                    }
                ]
            }]
        },
        {
            code: "new RegExp(`a(bc)d`)",
            errors: [{
                messageId: "required",
                type: "NewExpression",
                data: { group: "(bc)" },
                suggestions: [
                    {
                        messageId: "addGroupName",
                        output: "new RegExp(`a(?<temp1>bc)d`)"
                    },
                    {
                        messageId: "addNonCapture",
                        output: "new RegExp(`a(?:bc)d`)"
                    }
                ]
            }]
        },
        {
            code: "new RegExp('\u1234\u5678(?:a)(b)');",
            errors: [{
                messageId: "required",
                type: "NewExpression",
                data: { group: "(b)" },
                suggestions: [
                    {
                        messageId: "addGroupName",
                        output: "new RegExp('\u1234\u5678(?:a)(?<temp1>b)');"
                    },
                    {
                        messageId: "addNonCapture",
                        output: "new RegExp('\u1234\u5678(?:a)(?:b)');"
                    }
                ]
            }]
        },
        {
            code: "new RegExp('\\u1234\\u5678(?:a)(b)');",
            errors: [{
                messageId: "required",
                type: "NewExpression",
                data: { group: "(b)" },
                suggestions: null
            }]
        },
        {
            code: "/([0-9]{4})-(\\w{5})/",
            errors: [
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "([0-9]{4})" },
                    line: 1,
                    column: 1,
                    endColumn: 21,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/(?<temp1>[0-9]{4})-(\\w{5})/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/(?:[0-9]{4})-(\\w{5})/"
                        }
                    ]
                },
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "(\\w{5})" },
                    line: 1,
                    column: 1,
                    endColumn: 21,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/([0-9]{4})-(?<temp1>\\w{5})/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/([0-9]{4})-(?:\\w{5})/"
                        }
                    ]
                }
            ]
        },
        {
            code: "/([0-9]{4})-(5)/",
            errors: [
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "([0-9]{4})" },
                    line: 1,
                    column: 1,
                    endColumn: 17,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/(?<temp1>[0-9]{4})-(5)/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/(?:[0-9]{4})-(5)/"
                        }
                    ]
                },
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "(5)" },
                    line: 1,
                    column: 1,
                    endColumn: 17,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/([0-9]{4})-(?<temp1>5)/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/([0-9]{4})-(?:5)/"
                        }
                    ]
                }
            ]
        },
        {
            code: "/(?<temp2>(a))/",
            errors: [
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "(a)" },
                    line: 1,
                    column: 1,
                    endColumn: 16,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/(?<temp2>(?<temp3>a))/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/(?<temp2>(?:a))/"
                        }
                    ]
                }
            ]
        },
        {
            code: "/(?<temp2>(a)(?<temp5>b))/",
            errors: [
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "(a)" },
                    line: 1,
                    column: 1,
                    endColumn: 27,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/(?<temp2>(?<temp6>a)(?<temp5>b))/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/(?<temp2>(?:a)(?<temp5>b))/"
                        }
                    ]
                }
            ]
        },
        {
            code: "/(?<temp1>[0-9]{4})-(\\w{5})/",
            errors: [
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "(\\w{5})" },
                    line: 1,
                    column: 1,
                    endColumn: 29,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/(?<temp1>[0-9]{4})-(?<temp2>\\w{5})/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/(?<temp1>[0-9]{4})-(?:\\w{5})/"
                        }
                    ]
                }
            ]
        },
        {
            code: "/(?<temp1>[0-9]{4})-(5)/",
            errors: [
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "(5)" },
                    line: 1,
                    column: 1,
                    endColumn: 25,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/(?<temp1>[0-9]{4})-(?<temp2>5)/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/(?<temp1>[0-9]{4})-(?:5)/"
                        }
                    ]
                }
            ]
        },
        {
            code: "/(?<temp1>a)(?<temp2>a)(a)(?<temp3>a)/",
            errors: [
                {
                    messageId: "required",
                    type: "Literal",
                    data: { group: "(a)" },
                    line: 1,
                    column: 1,
                    endColumn: 39,
                    suggestions: [
                        {
                            messageId: "addGroupName",
                            output: "/(?<temp1>a)(?<temp2>a)(?<temp4>a)(?<temp3>a)/"
                        },
                        {
                            messageId: "addNonCapture",
                            output: "/(?<temp1>a)(?<temp2>a)(?:a)(?<temp3>a)/"
                        }
                    ]
                }
            ]
        },
        {
            code: "new RegExp('(' + 'a)')",
            errors: [{
                messageId: "required",
                type: "NewExpression",
                data: { group: "(a)" },
                suggestions: null
            }]
        },
        {
            code: "new RegExp('a(bc)d' + 'e')",
            errors: [{
                messageId: "required",
                type: "NewExpression",
                data: { group: "(bc)" },
                suggestions: null
