                data: { group: "(ab)" },
                suggestions: null
            }]
        },
        {
            code: "new RegExp(`(a)\n`)",
            errors: [{
                messageId: "required",
                type: "NewExpression",
                data: { group: "(a)" },
                line: 1,
                column: 1,
                endLine: 2,
                endColumn: 3,
                suggestions: [
                    {
                        messageId: "addGroupName",
                        output: "new RegExp(`(?<temp1>a)\n`)"
                    },
                    {
                        messageId: "addNonCapture",
                        output: "new RegExp(`(?:a)\n`)"
                    }
                ]
            }]
        },
        {
            code: "RegExp(`a(b\nc)d`)",
            errors: [{
                messageId: "required",
                type: "CallExpression",
                data: { group: "(b\nc)" },
                suggestions: [
                    {
                        messageId: "addGroupName",
                        output: "RegExp(`a(?<temp1>b\nc)d`)"
                    },
                    {
                        messageId: "addNonCapture",
                        output: "RegExp(`a(?:b\nc)d`)"
                    }
                ]
            }]
        },
        {
